use super::*;
use crate::cn::wps::moss::{app::{KmoBookApi::KmoBookApi,BookOpenListener::BookOpenListener,event::{KmoBookChangeEventsListener::KmoBookChangeEventsListener,KmoBookOpenPasswordProvider::KmoBookOpenPasswordProvider}},xlsxr::{handler::WorkbookHandler::WorkbookHandler,xl::XlsxrWorkbook::XlsxrWorkbook,util::UnifiedXmlReader::UnifiedXmlReader}};
use serde_json::{Value,json};use std::panic::{catch_unwind,AssertUnwindSafe};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let name=["NullPointerException","IllegalStateException","IllegalArgumentException","ArrayIndexOutOfBoundsException","RuntimeException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":name})}}}
fn record(r:&FileSharingRecord)->Value{json!({"readonly":r.getReadOnly(),"password":r.getPassword(),"user":r.getUsername(),"verifier":r.getPasswordModifyVerifier().map(|m|{let m=m.borrow();json!({"hash":m.getHashData(),"salt":m.getSaltData(),"spin":m.getSpinCount(),"algorithm":m.getAlogrithmSid()})})})}
fn state(c:&KmoBookCrypt)->Value{json!({"password":c.getPasswd(),"has":c.hasPasswd(),"type":c.getEncryptType(),"modify":c.hasModifyPasswd(),"record":c.getFileSharing().map(|r|record(&r)),"provider":c.getProviderInfo().map(|p|p.borrow().nInfoVersion),"backup":c.backupOtherEncryptHeadInfo.borrow().as_ref().map(|b|b.borrow().clone())})}
fn reset(c:&KmoBookCrypt){c.setPasswd__3(None,1,false);c.setFileSharing(None);c.setProviderInfo(None);*c.backupOtherEncryptHeadInfo.borrow_mut()=None;}
struct Listener{book:Rc<KmoBook>,c:Rc<KmoBookCrypt>,events:Rc<RefCell<Vec<Value>>>}
impl KmoBookChangeEventsListener for Listener{fn bookDidFinishInitializing(&self){}fn sheetDidFinishActivating(&self){}fn bookContentsDidFinishChanging(&self){}fn bookSettingsDidFinishChanging(&self){self.events.borrow_mut().push(json!({"dirty":self.book.isDirty(),"state":state(&self.c)}));}}
fn command(c:&KmoBookCrypt,book:&KmoBook,a:&Value)->Value{match a["op"].as_str().unwrap(){"set"=>c.setPasswd__3(a["value"].as_str(),a["type"].as_i64().unwrap()as i32,a["dirty"].as_bool().unwrap()),"setShort"=>c.setPasswd(a["value"].as_str()),"modify"=>c.setModifyPasswd(a["value"].as_str()),"bookModify"=>book.setModifyPassword(a["value"].as_str()),"bookWrite"=>book.setWritePassword(a["value"].as_str()),"check"=>return json!(c.isModifyPassword(a["value"].as_str())),"dirtyFalse"=>book.setDirty(false),"clearRecord"=>c.setFileSharing(None),"record"=>{let r=Rc::new(FileSharingRecord::new());r.setPassword(a["password"].as_i64().unwrap()as i16);r.setUsername(a["user"].as_str());r.setReadOnly(a["readonly"].as_i64().unwrap()as i16);if a.get("hash").is_some(){r.setPassword__verifier(Some(Rc::new(RefCell::new(ModifyVerifier::new_with_algorithm__nullable(a["hash"].as_str(),a["salt"].as_str(),a["spin"].as_i64().unwrap()as i32,a["algorithm"].as_i64().unwrap()as i32)))));}c.setFileSharing(Some(r.clone()));return json!(Rc::ptr_eq(&c.getFileSharing().unwrap(),&r));},"mutateRecord"=>c.getFileSharing().expect("NullPointerException").setUsername(Some("changed")),"provider"=>{let p=Rc::new(RefCell::new(ProviderInfo::new()));c.setProviderInfo(Some(p.clone()));p.borrow_mut().nInfoVersion=38;return json!(Rc::ptr_eq(&c.getProviderInfo().unwrap(),&p));},"backup"=>{let b=Rc::new(RefCell::new(vec![1,2,3]));*c.backupOtherEncryptHeadInfo.borrow_mut()=Some(b.clone());b.borrow_mut()[0]=9;return json!(Rc::ptr_eq(c.backupOtherEncryptHeadInfo.borrow().as_ref().unwrap(),&b));},s=>panic!("unknown {s}")}Value::Null}
struct Provider{values:Value,trace:Rc<RefCell<Vec<Value>>>,cursor:Cell<usize>,fail:String,crypt:Rc<KmoBookCrypt>}
impl KmoBookOpenPasswordProvider for Provider{
 fn getReadPassword(&self,_b:bool)->std::io::Result<Option<String>>{Ok(None)}fn verifyReadPassword(&self,_b:bool){}fn tryIfPasswdError(&self)->bool{false}
 fn getWritePassword(&self,b:bool)->Option<String>{self.trace.borrow_mut().push(json!({"call":"get","sha":b,"state":state(&self.crypt)}));if self.fail=="get"{panic!("IllegalStateException: observer get");}let i=self.cursor.get();let values=self.values.as_array().unwrap();if i>=values.len(){None}else{self.cursor.set(i+1);values[i].as_str().map(str::to_owned)}}
 fn verifyWritePassword(&self,b:bool){self.trace.borrow_mut().push(json!({"call":"verify","ok":b,"state":state(&self.crypt)}));if self.fail=="verify"{panic!("IllegalStateException: observer verify");}}
}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]fn original_android_book_crypt_file_sharing_and_password_provider_loop(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/book-crypt-r0b63");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let actual=book.getCryptInfo();let mut histories=vec![];for h in input["histories"].as_array().unwrap(){reset(&actual);book.setDirty(false);let c=if h["nullBook"]==true{Rc::new(KmoBookCrypt::new(Weak::new()))}else{actual.clone()};let events=Rc::new(RefCell::new(vec![]));let l:Rc<dyn KmoBookChangeEventsListener>=Rc::new(Listener{book:book.clone(),c:c.clone(),events:events.clone()});book.subscribeChangeEvents(Some(l.clone()));let mut rows=vec![];for a in h["commands"].as_array().unwrap(){let mut row=call(||command(&c,&book,a));row["state"]=state(&c);row["dirty"]=json!(book.isDirty());row["bookHasWrite"]=json!(book.hasWritePassword());row["events"]=json!(events.borrow().clone());rows.push(row);}book.unsubscribeChangeEvents(Some(&l));histories.push(rows);}
 let mut xml=vec![];for p in input["xml"].as_array().unwrap(){reset(&actual);let old=Rc::new(FileSharingRecord::new());old.setUsername(Some("previous"));old.setPassword(7);actual.setFileSharing(Some(old.clone()));book.setDirty(false);let trace=Rc::new(RefCell::new(vec![]));let provider=Rc::new(Provider{values:p["passwords"].clone(),trace:trace.clone(),cursor:Cell::new(0),fail:p["fail"].as_str().unwrap_or("").into(),crypt:actual.clone()});let reader=XlsxrWorkbook::XlsxrWorkbook(book.clone(),None,if p["nullListener"]==true{None}else{Some(Rc::new(BookOpenListener))},if p["nullProvider"]==true{None}else{Some(provider)});let mut row=call(||{UnifiedXmlReader::read(&mut std::io::Cursor::new(p["text"].as_str().unwrap().as_bytes()),Box::new(WorkbookHandler::WorkbookHandler(book.clone(),reader))).unwrap();Value::Null});row["state"]=state(&actual);row["sameOld"]=json!(actual.getFileSharing().is_some_and(|r|Rc::ptr_eq(&r,&old)));row["dirty"]=json!(book.isDirty());row["trace"]=json!(trace.borrow().clone());xml.push(row);}reset(&actual);let out=json!({"histories":histories,"sameFacade":Rc::ptr_eq(&book.getCryptInfo(),&actual),"xml":xml});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();compare(&out,&java,"root");}
